\maketitle

\begin{abstract}
Let $f$ be an odd prime and let $\Q(\zeta_f)$ be the $f$-th cyclotomic field, whose Galois group is the cyclic group $C_n \cong (\Z/f)^\times$ of order $n = f-1$. For an unramified rational prime $p$ the \emph{splitting type} $T(p)=\ord_f(p)$ --- the residue degree, equivalently the order of the Frobenius element --- is the complete factorisation datum of $p$. We analyse the information carried by this multi-state observable and by its semiprime analogue: given only the norm class $N \bmod f$ of a semiprime $N=pq$, how much is revealed about the unordered pair $\{T(p),T(q)\}$?
We prove: (i) the type is a deterministic function of the residue, so the residue-to-type channel is exact, $I(p \bmod f\,;\,T)=H(T)$, and refining the observation modulus adds nothing; the type distribution is the Euler law $\Pr[T=d]=\varphi(d)/n$ over $d \mid n$, giving $H(T)=\log_2 n - \frac1n\sum_{d\mid n}\varphi(d)\log_2\varphi(d)$; (ii) the binary ``splits completely'' readout has entropy exactly $H_2(1/n)$, equal to $H(T)$ if and only if $n$ is prime, hence strictly lossy for composite $n$; (iii) the semiprime type-pair channel $\Ipair(n)=H(\Pi)-\frac1n\sum_c H(\Pi_c)$ is exactly computable, with $\Ipair(2)=1$, $\Ipair(4)=5/4$, $\Ipair(6)=\log_2 3 - 1/9$, $\Ipair(8)=21/16$, $\Ipair(12)=\log_2 3 + 5/36$, $\Ipair(16)=85/64$ and further exact forms for $n \le 20$: the quadratic case sits exactly at the classical one-bit cap, every even order $n \ge 4$ strictly exceeds it, and every odd order $n\ge3$ stays strictly below; (iv) the structure laws $\Ipair(mk)=\Ipair(m)+\Ipair(k)$ for coprime $m,k$, $\Ipair(2m)=\Ipair(m)+1$ for odd $m$, and $\Ipair(2^k)=\frac43(1-4^{-k})$ with supremum $4/3$.
The one-bit ceiling for symmetric semiprime forks is thus a bound on \emph{binary} observables, not on what a norm class can reveal.
\end{abstract}

\section{Introduction}

\subsection{The binary-fork cap}

Fix a quadratic field $K=\Q(\sqrt D)$ and let $\chi(p)=\left(\frac{D}{p}\right)\in\{\pm1\}$ record whether $p$ splits or is inert in $K$. For a semiprime $N=pq$ the symbol is multiplicative, $\chi(N)=\chi(p)\chi(q)$, so the observer of $N$ receives exactly the \emph{product} of the two hidden bits. If $\chi(p),\chi(q)$ are independent fair bits, the unordered pair takes the values $\{+,+\},\{+,-\},\{-,-\}$ with probabilities $\tfrac14,\tfrac12,\tfrac14$, of entropy $\tfrac32$ bits; conditioning on the parity leaves residual entropy $\tfrac12$. The mutual information is exactly $1$ bit.

This is the \emph{binary-fork cap}: a symmetric semiprime fork built from a two-state character is worth at most one bit, and the quadratic fork saturates it. The cap has functioned as a folk theorem --- a product of two primes discloses one bit about the pair.

\subsection{Multi-state splitting types}

The cap is an artifact of asking a two-state question. Let $f$ be an odd prime and $\zeta_f$ a primitive $f$-th root of unity, so that
\[
\operatorname{Gal}(\Q(\zeta_f)/\Q)\cong(\Z/f)^\times\cong C_n,\qquad n=f-1,
\]
via $\sigma_a(\zeta_f)=\zeta_f^a$. For $p \nmid f$ the Frobenius element is $\sigma_p$, and $p$ factors in $\Z[\zeta_f]$ into $g=n/T$ distinct prime ideals of common residue degree $T$, where
\[
T(p)=\ord_f(p)=\min\{k\ge1:\ p^k\equiv1 \bmod f\}
\]
is the order of $\sigma_p$ in $C_n$. The divisor $T(p)\mid n$ is the \emph{complete splitting type}: it determines the entire factorisation pattern. The classical binary observable, the root count $\nr(p)$ of the defining polynomial mod $p$, distinguishes only $T=1$ from $T>1$ and is one shadow of the type. We show that the shadow is strictly smaller than the object, and that the object breaks the cap.

\subsection{The finite cyclic model}

All statements below are theorems about a finite cyclic group and hold for every order $n\ge1$. Writing $C_n$ additively as $\Z/n$ --- the discrete logarithm with respect to a primitive root mod $f$ converts multiplication of residues into addition --- the type becomes the additive order
\[
T(x)=\frac{n}{\gcd(n,x)},\qquad x\in\Z/n,
\]
and the norm $N=pq$ becomes the norm class $x+y \bmod n$. Under Chebotarev equidistribution the Frobenius residues are asymptotically uniform, so the uniform measure on $\Z/n$ is the correct model, and every information quantity below is a finite, exactly computable real number.

\section{Definitions and the counting form of entropy}

All logarithms are base $2$ and entropies are in bits. For occupation numbers $c_1,\dots,c_m$ with total $t=\sum_i c_i$ put
\[
H(c_1,\dots,c_m;t)=-\sum_{i:\,c_i>0}\frac{c_i}{t}\log_2\frac{c_i}{t}.
\]

\begin{lemma}[Counting form]\label{lem:count}
If $\sum_i c_i=t>0$ then $H(c_1,\dots,c_m;t)=\log_2 t-\frac1t\sum_i c_i\log_2 c_i$, with $0\log_2 0=0$.
\end{lemma}

\begin{proof}
Expand $\log_2(c_i/t)=\log_2 c_i-\log_2 t$ for $c_i>0$ and use $\sum_i c_i=t$.
\end{proof}

Every entropy below is therefore a $\Q$-linear combination of $1$ and terms $\log_2\ell$ for small primes $\ell$; all ``exact values'' lie in that space.

\begin{definition}
For $x\in\Z/n$ the \emph{splitting type} is $T(x)=n/\gcd(n,x)$, the additive order of $x$. The \emph{root-count readout} is the binary coarsening $\nr(x)=\mathbf{1}[T(x)=1]$. For independent uniform $x,y\in\Z/n$, the \emph{unordered type pair} is $\Pi(x,y)=\{T(x),T(y)\}$ and the \emph{norm class} is $\nu(x,y)=x+y \bmod n$.
\end{definition}

\section{The single-prime channel}

\begin{theorem}[Exactness of the residue-to-type channel]\label{thm:det}
For every $n\ge1$ and $x$ uniform on $\Z/n$, $I(x\,;\,T(x))=H(T)$; equivalently $H(T\mid x)=0$.
\end{theorem}

\begin{proof}
The joint variable $(x,T(x))$ is supported on the graph of $T$, which is in bijection with $\Z/n$, so $H(x,T)=H(x)=\log_2 n$ and $I(x;T)=H(x)+H(T)-H(x,T)=H(T)$.
\end{proof}

\begin{theorem}[Thickening zero]\label{thm:thick}
If $a\equiv b \pmod n$ then $T(a)=T(b)$. Hence $T(a \bmod nm)=T(a)$ for all $m\ge1$: observing the residue modulo any multiple of $n$ --- in particular modulo $f^2$ rather than $f$ --- yields no additional information about the type.
\end{theorem}

\begin{proof}
By the Euclidean step $\gcd(n,a)=\gcd(a\bmod n,n)$, the gcd depends only on $a \bmod n$, hence so does $T(a)=n/\gcd(n,a)$; apply this with $b=a\bmod nm$ and $n\mid nm$.
\end{proof}

\begin{theorem}[Euler-$\varphi$ type law]\label{thm:euler}
For $n>0$ and $d\mid n$,
\[
\#\{x\in\Z/n:\ T(x)=d\}=\varphi(d),\qquad\text{i.e.}\qquad \Pr[T=d]=\frac{\varphi(d)}{n}.
\]
\end{theorem}

\begin{proof}
Since $\gcd(n,x)\mid n$ and $d \mid n$, we have $T(x)=d$ iff $\gcd(n,x)=n/d$. Writing $x=(n/d)u$ with $0\le u<d$, this becomes $\gcd(d,u)=1$, which has $\varphi(d)$ solutions.
\end{proof}

\begin{corollary}
Summing over $d\mid n$ recovers $\sum_{d\mid n}\varphi(d)=n$: every residue has exactly one type, and the realised types are precisely the divisors of $n$.
\end{corollary}

\begin{theorem}[Closed form for the type entropy]\label{thm:HT}
For every $n>0$,
\[
H(T)=\log_2 n-\frac1n\sum_{d\mid n}\varphi(d)\log_2\varphi(d).
\]
In particular, for prime $n=\ell$ the type is binary and $H(T)=\log_2\ell-\frac{\ell-1}{\ell}\log_2(\ell-1)$.
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:euler} with Lemma~\ref{lem:count} and $\sum_{d\mid n}\varphi(d)=n$.
\end{proof}

\begin{example}
$n=4$ ($\Q(\zeta_5)$): types $\{1,2,4\}$ with rates $\tfrac14,\tfrac14,\tfrac12$, $H(T)=\tfrac32$ exactly.
$n=6$ ($\Q(\zeta_7)$): types $\{1,2,3,6\}$ with rates $\tfrac16,\tfrac16,\tfrac13,\tfrac13$, $H(T)=\log_2 3+\tfrac13\approx1.9183$.
$n=12$ ($\Q(\zeta_{13})$): six types, $H(T)=\log_2 3+\tfrac56\approx2.4183$.
\end{example}

\section{The root count is strictly lossy}

\begin{theorem}[Splits-completely pinning]\label{thm:pin}
For every $n>0$ exactly one residue has type $1$, so the binary root-count readout has occupation numbers $(1,n-1)$ and
\[
H(\nr)=\log_2 n-\frac{n-1}{n}\log_2(n-1)=H_2\!\left(\tfrac1n\right).
\]
\end{theorem}

\begin{proof}
$T(x)=1$ iff $x=0$ (Theorem~\ref{thm:euler} with $d=1$, $\varphi(1)=1$); apply Lemma~\ref{lem:count}.
\end{proof}

For $n=4$ this is the \emph{quartic pinning} $H(\nr)=2-\tfrac34\log_2 3\approx0.8113$; for $n=6$ it is $1+\log_2 3-\tfrac56\log_2 5\approx0.6500$.

\begin{theorem}[Lossiness dichotomy]\label{thm:lossy}
$H(\nr)\le H(T)$ always, with equality if and only if $n$ is prime (or $n=1$). In particular $H(\nr)<H(T)$ for $n=4$ ($0.8113<1.5$) and $n=6$ ($0.6500<1.9183$).
\end{theorem}

\begin{proof}
$\nr$ is a deterministic function of $T$, so $H(\nr)\le H(T)$ by coarsening. Equality requires the coarsening to be injective on the support, i.e.\ $T$ takes only two values, i.e.\ $n$ has exactly two divisors. For prime $n$, Theorems~\ref{thm:HT} and~\ref{thm:pin} give the same expression.
\end{proof}

For $\Q(\zeta_5)$ the root count merges the factorisation patterns $[2,2]$ and $[4]$; for $\Q(\zeta_7)$ it merges $[2,2,2]$, $[3,3]$ and $[6]$. The type, not the root count, is the complete object.

\section{The semiprime type-pair channel}

\begin{definition}\label{def:Ipair}
Let $x,y$ be independent and uniform on $\Z/n$, let $\Pi$ be the law of the unordered type pair and $\Pi_c$ its law conditioned on $x+y=c$. The \emph{type-pair channel capacity} is
\[
\Ipair(n)=I(\nu\,;\,\Pi)=H(\Pi)-\frac1n\sum_{c\in\Z/n}H(\Pi_c),
\]
the weight $1/n$ being the (uniform) law of the norm class.
\end{definition}

\begin{theorem}[Exact evaluability]\label{thm:eval}
Let $P_k$ be the occupation numbers of the unordered type pairs among all $n^2$ ordered pairs and $C_{c,k}$ those within the fibre $x+y=c$. Then $\sum_k P_k=n^2$, $\sum_k C_{c,k}=n$, and
\[
\Ipair(n)=\Big(\log_2 n^2-\tfrac1{n^2}\sum_k P_k\log_2 P_k\Big)-\frac1n\sum_c\Big(\log_2 n-\tfrac1n\sum_k C_{c,k}\log_2 C_{c,k}\Big).
\]
Hence $\Ipair(n)\in\Q+\sum_\ell\Q\log_2\ell$, computable by finite enumeration.
\end{theorem}

\begin{proof}
Lemma~\ref{lem:count} applied to $P$ with total $n^2$ and to each $C_c$ with total $n$.
\end{proof}

\subsection{Worked example: \texorpdfstring{$n=4$}{n=4}, the field \texorpdfstring{$\Q(\zeta_5)$}{Q(zeta5)}}

Types on $\Z/4$ are $T(0)=1$, $T(1)=4$, $T(2)=2$, $T(3)=4$. The sixteen ordered pairs give
\[
\{1,1\}:1,\quad\{1,2\}:2,\quad\{2,2\}:1,\quad\{1,4\}:4,\quad\{2,4\}:4,\quad\{4,4\}:4,
\]
so $H(\Pi)=4-\tfrac{38}{16}=\tfrac{19}{8}$. The conditional tables are:

\begin{center}
\begin{tabular}{ccccccc c}
\toprule
$c$ & $\{1,1\}$ & $\{1,2\}$ & $\{2,2\}$ & $\{1,4\}$ & $\{2,4\}$ & $\{4,4\}$ & $H(\Pi_c)$\\
\midrule
$0$ & 1 & 0 & 1 & 0 & 0 & 2 & $1.5$\\
$1$ & 0 & 0 & 0 & 2 & 2 & 0 & $1$\\
$2$ & 0 & 2 & 0 & 0 & 0 & 2 & $1$\\
$3$ & 0 & 0 & 0 & 2 & 2 & 0 & $1$\\
\bottomrule
\end{tabular}
\end{center}

Hence $H(\Pi\mid\nu)=\tfrac98$ and $\Ipair(4)=\tfrac{19}{8}-\tfrac98=\tfrac54=1.25>1$: the cap is exceeded, exactly and unconditionally.

