SYMBOLIC VALUE  v = (q0, {l -> q_l})  represents  q0 + sum_l q_l * log2(l),  q rational

function SymLog2(m):
    v <- (0, {})
    for each prime power l^e in the factorisation of m:
        if l = 2 then q0 <- q0 + e  else  q_l <- q_l + e
    return v

function SymEntropy(counts, total):
    v <- SymLog2(total)
    for c in counts with c > 1:
        v <- v + (-c/total) * SymLog2(c)          # exact rational scaling
    return v

function SymChannel(n):
    build pairCount and cond[.] as in the enumeration algorithm
    v <- SymEntropy(pairCount, n^2)
    for c in 0..n-1:  v <- v + (-1/n) * SymEntropy(cond[c], n)
    return v                                      # the exact closed form

algorithms.code:
"""Exact symbolic evaluation of the cyclic type-pair channel.

Every entropy occurring in the channel has the counting form
    H = log2(t) - (1/t) * sum_c c*log2(c),
so with all occupation numbers integral the value lies in the Q-vector space
spanned by 1 and {log2 l : l prime}.  Factoring each occupation number turns the
whole computation into exact rational arithmetic: no floating point is used, and
the output is a closed form such as  I_pair(12) = 5/36 + 1*log2(3).
"""

from __future__ import annotations

from collections import Counter, defaultdict
from fractions import Fraction
from math import gcd
from typing import Dict, List, Tuple

# A symbolic value is  rational part (the coefficient of log2 2 = 1)  plus
# a dictionary {odd prime: coefficient}.
Symbolic = Tuple[Fraction, Dict[int, Fraction]]


def factorise(m: int) -> Dict[int, int]:
    """Prime factorisation of m >= 1 by trial division."""
    out: Dict[int, int] = {}
    d, mm = 2, m
    while d * d <= mm:
        while mm % d == 0:
            out[d] = out.get(d, 0) + 1
            mm //= d
        d += 1
    if mm > 1:
        out[mm] = out.get(mm, 0) + 1
    return out


def zero() -> Symbolic:
    return Fraction(0), defaultdict(Fraction)


def add(a: Symbolic, b: Symbolic, scale: Fraction = Fraction(1)) -> Symbolic:
    """a + scale * b."""
    rat = a[0] + scale * b[0]
    logs: Dict[int, Fraction] = defaultdict(Fraction, a[1])
    for p, c in b[1].items():
        logs[p] += scale * c
    return rat, logs


def log2_of(m: int) -> Symbolic:
    """Exact symbolic log2(m) for a positive integer m."""
    rat, logs = Fraction(0), defaultdict(Fraction)
    for p, e in factorise(m).items():
        if p == 2:
            rat += e
        else:
            logs[p] += e
    return rat, logs


def symbolic_entropy(counts: List[int], total: int) -> Symbolic:
    """log2(total) - (1/total) * sum c log2 c, exactly."""
    value = log2_of(total)
    for c in counts:
        if c > 1:
            value = add(value, log2_of(c), Fraction(-c, total))
    return value


def splitting_type(n: int, x: int) -> int:
    return n // gcd(n, x)


def symbolic_pair_channel(n: int) -> Symbolic:
    """Exact I_pair(n) = H(Pi) - (1/n) sum_c H(Pi_c) as a symbolic value."""
    glob: Counter = Counter()
    fibres: List[Counter] = [Counter() for _ in range(n)]
    for x in range(n):
        tx = splitting_type(n, x)
        for y in range(n):
            ty = splitting_type(n, y)
            key = (min(tx, ty), max(tx, ty))
            glob[key] += 1
            fibres[(x + y) % n][key] += 1
    value = symbolic_entropy(list(glob.values()), n * n)
    for fib in fibres:
        value = add(value, symbolic_entropy(list(fib.values()), n), Fraction(-1, n))
    return value


def render(value: Symbolic) -> str:
    rat, logs = value
    parts = [str(rat)] if rat else []
    for p in sorted(logs):
        c = logs[p]
        if c:
            parts.append(f"{c}*log2({p})")
    return " + ".join(parts) if parts else "0"


if __name__ == "__main__":
    for n in [2, 3, 4, 5, 6, 8, 9, 10, 12, 15, 16, 18, 20]:
        print(f"I_pair({n:2d}) = {render(symbolic_pair_channel(n))}")
